const row=(a,b)=>`<div class="spec-row"><span>${a}</span><strong>${b}</strong></div>`;
const specs={
  'TE Series':[row('Models','TE46 / TE4Z · TE8L / TE8K · TE9L / TE9B · TE8M / TE8P'),row('Drive','4×2 / 6×4'),row('GCW','42,000–120,000 kg'),row('Battery','CATL 400 / 466 / 497 / 600 kWh by model'),row('Motor','LvKong 315–400 kW rated / 510–550 kW peak'),row('Transmission','LvKong 4AMT'),row('Charging','Dual-gun 500–600 A; GB or EU interface by model'),row('Safety','EBS + ESC, LDWS + FCWS on listed models')].join(''),
  'KT / KTH Series':[row('Models','KT5M / KT5J · KTH1 / KTH2 / KTH3'),row('Drive','4×2 / 8×4'),row('GVW','18,000–31,000 kg'),row('Battery','CATL 262–400 kWh by model'),row('Motor','LvKong 150–270 kW rated / up to 450 kW peak'),row('Transmission','4-speed electric drive axle'),row('Body capability','Approx. 6.8–9.8 m; box, flatbed and specialist bodies'),row('Highlights','Up to 400 km stated for selected 4×2 configuration')].join(''),
  'TZ Series':[row('Models','KTA1 · TZ3Z / TZ4Y · TZ5E / TZ3V / TZ5Y'),row('Drive','6×4 / 8×4'),row('GVW','31,000–80,000 kg'),row('Battery','CATL 352 / 400 / 600 kWh'),row('Motor','LvKong 270–400 kW rated / 450–550 kW peak'),row('Transmission','LvKong 4AMT'),row('Frame','Reinforced multi-layer frames by duty class'),row('Options','TZ4Y / TZ5Y right-hand drive; EU interface on TZ4Y')].join(''),
  'Special Vehicles':[row('Models','KT3F · KT1D · KT3E · KT7A · TZ2E · TZ8J / KT9X'),row('Drive','4×2 / 6×4 / 8×4'),row('GVW','18,000–45,000 kg'),row('Battery','CATL 166–410 kWh'),row('Motor','LvKong systems up to 350 / 520 kW'),row('Applications','Sprinkler, sweeper, refuse and concrete mixer'),row('Charging','GB; selected EU-interface configurations'),row('Compliance','KT9X lists WVTA GSR2 safety package')].join('')
};
document.querySelector('.menu').addEventListener('click',e=>{const h=document.querySelector('.topbar');h.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',h.classList.contains('open'))});
document.querySelectorAll('.filters button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.filters button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');document.querySelectorAll('.product-card').forEach(card=>card.classList.toggle('hidden',btn.dataset.filter!=='all'&&card.dataset.category!==btn.dataset.filter))}));
const dialog=document.querySelector('#specDialog');document.querySelectorAll('.details').forEach(btn=>btn.addEventListener('click',()=>{document.querySelector('#dialogTitle').textContent=btn.dataset.model;document.querySelector('#dialogBody').innerHTML=specs[btn.dataset.model];dialog.showModal()}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
document.querySelector('#quoteForm').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);const message=encodeURIComponent(`Dongfeng EV inquiry\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nCountry: ${d.get('country')}\nVehicle: ${d.get('vehicle')}\nProject details: ${d.get('message')||'Please contact me with a suitable configuration.'}`);document.querySelector('.form-status').textContent='Opening WhatsApp with your inquiry details…';window.open(`https://wa.me/8618591976330?text=${message}`,'_blank','noopener')});
const slides=[...document.querySelectorAll('.hero-slide')],dots=[...document.querySelectorAll('.slider-nav button')];let currentSlide=0,slideTimer;function showSlide(i){currentSlide=(i+slides.length)%slides.length;slides.forEach((s,n)=>s.classList.toggle('active',n===currentSlide));dots.forEach((d,n)=>d.classList.toggle('active',n===currentSlide))}function restartSlider(){clearInterval(slideTimer);slideTimer=setInterval(()=>showSlide(currentSlide+1),6500)}document.querySelector('.slider-arrow.prev').addEventListener('click',()=>{showSlide(currentSlide-1);restartSlider()});document.querySelector('.slider-arrow.next').addEventListener('click',()=>{showSlide(currentSlide+1);restartSlider()});dots.forEach((d,i)=>d.addEventListener('click',()=>{showSlide(i);restartSlider()}));document.querySelector('.hero-carousel').addEventListener('mouseenter',()=>clearInterval(slideTimer));document.querySelector('.hero-carousel').addEventListener('mouseleave',restartSlider);restartSlider();
